var datum, txt, Reboot_Timer, Fault_Reboot_Timer, Counter_Reboot_Timer;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------->> Verbindung überwachen
// WLan
on({ id: 'go-e.0.info.connection' /* If communication with circuit works */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') == true) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'GO - Wlan Verbindung wieder hergestellt.');
    console.debug('go-e / --> Wlan Verbindung wieder hergestellt');
    sendTo('telegram.0', 'send', {
      text: 'go-e / --> Wlan Verbindung wieder hergestellt',
    });
  } else {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'GO - Wlan Verbindung verloren!');
    console.debug('go-e / --> Wlan Verbindung verloren !');
    sendTo('telegram.0', 'send', {
      text: 'go-e / --> Wlan Verbindung verloren !',
    });
  }
});
// Kommunikation
Reboot_Timer = getState('go-e.0.reboot_timer').val;
Fault_Reboot_Timer = false;
on({ id: 'go-e.0.reboot_timer' /* reboot_timer (rbtz) */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  Reboot_Timer = getState('go-e.0.reboot_timer').val;
  Counter_Reboot_Timer = 0;
  if (Fault_Reboot_Timer) {
    Fault_Reboot_Timer = false;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'GO - Verbindung wieder hergestellt (Reboot Timer)!');
    console.debug('go-e / --> Verbindung wieder hergestellt (Reboot Timer) !');
    sendTo('telegram.0', 'send', {
      text: 'go-e / --> Verbindung wieder hergestellt (Reboot Timer) !',
    });
  }
});
schedule("* * * * * *", async () => {
  Counter_Reboot_Timer = (typeof Counter_Reboot_Timer === 'number' ? Counter_Reboot_Timer : 0) + 1;
  if (Counter_Reboot_Timer >= 120 && getState('go-e.0.reboot_timer').val == Reboot_Timer && !Fault_Reboot_Timer) {
    Fault_Reboot_Timer = true;
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'GO - Verbindung verloren (Reboot Timer)!');
    console.debug('go-e / --> Verbindung verloren (Reboot Timer) !');
    sendTo('telegram.0', 'send', {
      text: 'go-e / --> Verbindung verloren (Reboot Timer) !',
    });
  }
});

// ------>>> Emergency STOP
on({ id: [].concat(['0_userdata.0.go-e-phases.L1_Zuleitung']).concat(['0_userdata.0.go-e-phases.L2_Zuleitung']).concat(['0_userdata.0.go-e-phases.L3_Zuleitung']), change: 'ne' }, async (obj) => {
  if (getState('0_userdata.0.go-e-phases.L1_Zuleitung').val == false || getState('0_userdata.0.go-e-phases.L2_Zuleitung').val == false || getState('0_userdata.0.go-e-phases.L3_Zuleitung').val == false) {
    setState('0_userdata.0.go-e-phases.go_E_Zuleitung_Emergency_STOP' /* go_E_Zuleitung_Emergency_STOP */, true);
    console.debug('go_E Zuleitung - Emergency STOP !!!');
    sendTo('telegram.0', 'send', {
      text: 'go_E Zuleitung - Emergency STOP !!!',
    });
  } else if (getState('0_userdata.0.go-e-phases.L1_Zuleitung').val == true && getState('0_userdata.0.go-e-phases.L2_Zuleitung').val == true && getState('0_userdata.0.go-e-phases.L3_Zuleitung').val == true) {
    setState('0_userdata.0.go-e-phases.go_E_Zuleitung_Emergency_STOP' /* go_E_Zuleitung_Emergency_STOP */, false);
    console.debug('go_E Zuleitung - Emergency STOP wieder deaktiviert.');
    sendTo('telegram.0', 'send', {
      text: 'go_E Zuleitung - Emergency STOP wieder deaktiviert.',
    });
  }
});


